var sveltekit_default = "---\nlayout: article\ntitle: Start with SvelteKit\ndescription: Learn how to use Appwrite to add authentication, user management, file storage, and more to your SvelteKit apps.\ndifficulty: beginner\nreadtime: 3\nback: /docs/quick-starts\n---\nLearn how to setup your first SvelteKit project powered by Appwrite.\n{% section #step-1 step=1 title=\"Create project\" %}\nHead to the [Appwrite Console](https://cloud.appwrite.io/console).\n\n{% only_dark %}\n![Create project screen](/images/docs/quick-starts/dark/create-project.avif)\n{% /only_dark %}\n{% only_light %}\n![Create project screen](/images/docs/quick-starts/create-project.avif)\n{% /only_light %}\n\nIf this is your first time using Appwrite, create an account and create your first project.\n\nThen, under **Add a platform**, add a **Web app**. The **Hostname** should be `localhost`.\n\n{% partial file=\"note-on-cors.md\" /%}\n\n{% only_dark %}\n![Add a platform](/images/docs/quick-starts/dark/add-platform.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a platform](/images/docs/quick-starts/add-platform.avif)\n{% /only_light %}\n\nYou can skip optional steps.\n\n{% /section %}\n{% section #step-2 step=2 title=\"Create SvelteKit project\" %}\nCreate a SvelteKit project.\n\n```sh\nnpx sv create\n```\n{% /section %}\n{% section #step-3 step=3 title=\"Install Appwrite\" %}\n\nInstall the JavaScript Appwrite SDK.\n\n```sh\nnpm install appwrite\n```\n{% /section %}\n{% section #step-4 step=4 title=\"Import Appwrite\" %}\nFind your project's ID in the **Settings** page.\n\n{% only_dark %}\n![Project settings screen](/images/docs/quick-starts/dark/project-id.avif)\n{% /only_dark %}\n{% only_light %}\n![Project settings screen](/images/docs/quick-starts/project-id.avif)\n{% /only_light %}\nCreate a new file `src/lib/appwrite.js` and add the following code to it, replace `<PROJECT_ID>` with your project ID.\n\n```client-web\nimport { Client, Account } from 'appwrite';\n\nexport const client = new Client();\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')\n    .setProject('<PROJECT_ID>'); // Replace with your project ID\n\nexport const account = new Account(client);\nexport { ID } from 'appwrite';\n```\n{% /section %}\n{% section #step-5 step=5 title=\"Create a login page\" %}\nReplace the contents of `src/routes/+page.svelte` with the following code.\n\n```html\n<script>\n    import { account, ID } from '$lib/appwrite';\n\n    let loggedInUser = null;\n\n    async function login(email, password) {\n        await account.createEmailPasswordSession({\n            email,\n            password\n        });\n        loggedInUser = await account.get();\n    }\n\n    async function register(email, password) {\n        await account.create({\n            userId: ID.unique(),\n            email,\n            password\n        });\n        login(email, password);\n    }\n\n    function submit(e) {\n        e.preventDefault();\n        const formData = new FormData(e.target);\n        const type = e.submitter.dataset.type;\n\n        if (type === \"login\") {\n            login(formData.get('email'), formData.get('password'));\n        } else if (type === \"register\") {\n            register(formData.get('email'), formData.get('password'));\n        }\n    }\n\n    async function logout() {\n        await account.deleteSession({ sessionId: 'current' });\n        loggedInUser = null;\n    }\n<\/script>\n\n<p>\n    {loggedInUser ? `Logged in as ${loggedInUser.name}` : 'Not logged in'}\n</p>\n\n<form on:submit={submit}>\n    <input type=\"email\" placeholder=\"Email\" name=\"email\" required />\n    <input type=\"password\" placeholder=\"Password\" name=\"password\" required />\n\n    <button type=\"submit\" data-type=\"login\">Login</button>\n    <button type=\"submit\" data-type=\"register\">Register</button>\n</form>\n\n<button on:click={logout}>Logout</button>\n```\n{% /section %}\n\n{% section #step-6 step=6 title=\"All set\" %}\nRun your project with `npm run dev` and open [localhost on port 5173](http://localhost:5173) in your browser.\n{% /section %}\n\n\n";
export { sveltekit_default as default };
